import CoreText
import Foundation
import OSLog
import UIKit

/// Registers the bundled Space Grotesk faces for this process.
///
/// Registering at launch (instead of listing them under `UIAppFonts`) keeps the
/// Info.plist fully generated by the build settings, and a missing file is a
/// logged warning rather than a silent fallback to the system font.
enum FontRegistry {
    private static let logger = Logger(subsystem: "com.nicomeuwly.hydravia", category: "Fonts")

    static func registerBrandFonts(bundle: Bundle = .main) {
        for face in BrandFont.allCases {
            guard let url = bundle.url(forResource: fileName(for: face), withExtension: "ttf") else {
                logger.error("Missing font file for \(face.rawValue, privacy: .public)")
                continue
            }
            var unmanagedError: Unmanaged<CFError>?
            guard !CTFontManagerRegisterFontsForURL(url as CFURL, .process, &unmanagedError),
                  let error = unmanagedError?.takeRetainedValue()
            else { continue }
            // Already registered (SwiftUI previews re-running) is expected;
            // anything else means the brand font silently fell back.
            if CFErrorGetCode(error) != CTFontManagerError.alreadyRegistered.rawValue {
                logger.error("Font \(face.rawValue, privacy: .public) failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }

    /// Navigation titles in the brand font, so system-built screens
    /// (Settings' list, sheets) match the custom ones.
    static func applyNavigationBarFonts() {
        // Title attributes only: replacing the bar's appearance objects would
        // switch off iOS 26's glass bar and scroll-edge effect.
        let bar = UINavigationBar.appearance()
        if let large = UIFont(name: BrandFont.bold.rawValue, size: 34) {
            bar.largeTitleTextAttributes = [.font: UIFontMetrics(forTextStyle: .largeTitle).scaledFont(for: large)]
        }
        if let inline = UIFont(name: BrandFont.bold.rawValue, size: 17) {
            bar.titleTextAttributes = [.font: UIFontMetrics(forTextStyle: .headline).scaledFont(for: inline)]
        }
    }

    private static func fileName(for face: BrandFont) -> String {
        switch face {
        case .regular: "SpaceGrotesk_400Regular"
        case .medium: "SpaceGrotesk_500Medium"
        case .semiBold: "SpaceGrotesk_600SemiBold"
        case .bold: "SpaceGrotesk_700Bold"
        }
    }
}
